class C:
    def helper(self): events.append('C.helper')
    def run(self): self.helper()
C().run()

class C:
    @staticmethod
    def helper(): events.append('C.helper')
    def run(self): self.helper()
C().run()

class D:
    def helper(self): events.append('D.helper')
class C:
    def helper(self): events.append('C.helper')
    def run(self):
        self = D()
        self.helper()
C().run()

class C:
    def helper(self): events.append('C.helper')
    def run(self): self.helper()
class D(C):
    def helper(self): events.append('D.helper')
D().run()

class C:
    def helper(self): events.append('C.helper')
    def run(self):
        self.helper = lambda: events.append('replacement')
        self.helper()
C().run()

class D:
    def helper(self): events.append('D.helper')
class C:
    def helper(self): events.append('C.helper')
    @staticmethod
    def run(self): self.helper()
C.run(D())

def replace(fn):
    return lambda self: events.append('replacement')
class C:
    @replace
    def helper(self): events.append('C.helper')
    def run(self): self.helper()
C().run()

class C:
    @staticmethod
    def helper(): events.append('C.helper')
    def run(self):
        def inner(): self.helper()
        inner()
C().run()
